from flask import Flask, request, send_file, abort
import os

app = Flask(__name__)

@app.route('/download')
def download_file():
    filename = request.args.get('filename')

    # Validate filename - only allow alphanumeric and some special chars
    if not filename or not all(c.isalnum() or c in '._-' for c in filename):
        abort(400, 'Invalid filename')

    base_dir = '/var/www/downloads'
    file_path = os.path.join(base_dir, filename)

    # Check if the normalized path is still within the base directory
    real_path = os.path.realpath(file_path)
    if not real_path.startswith(os.path.realpath(base_dir)):
        abort(403, 'Access denied')

    if not os.path.isfile(real_path):
        abort(404, 'File not found')

    return send_file(real_path)

if __name__ == '__main__':
    app.run(debug=False)

