from flask import Flask, request, jsonify

app = Flask(__name__)

# Simulated user database
users = {
    1: {'id': 1, 'username': 'user1', 'role': 'user', 'profile': 'Regular user profile'},
    2: {'id': 2, 'username': 'admin', 'role': 'admin', 'profile': 'Admin user profile'}
}

# Simulated authentication - normally would use sessions/tokens
def get_current_user():
    user_id = int(request.headers.get('user-id', 0))
    return users.get(user_id)

# Decorators for authorization
def require_authentication(f):
    def decorated(*args, **kwargs):
        current_user = get_current_user()
        if not current_user:
            return jsonify({'error': 'Authentication required'}), 401
        return f(current_user, *args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

@app.route('/profile/<int:user_id>', methods=['GET'])
@require_authentication
def get_user_profile(current_user, user_id):
    # Check if user has permission to access this profile
    if current_user['id'] != user_id and current_user['role'] != 'admin':
        # Log access control violation attempt
        app.logger.warning(
            f"Access control violation: User {current_user['id']} attempted to access profile {user_id}"
        )
        return jsonify({'error': 'Access denied'}), 403

    # Get the requested user profile
    user = users.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({
        'profile': user['profile'],
        'username': user['username']
    })

# Route to get current user's own profile
@app.route('/profile', methods=['GET'])
@require_authentication
def get_own_profile(current_user):
    return jsonify({
        'profile': current_user['profile'],
        'username': current_user['username'],
        'role': current_user['role']
    })

if __name__ == '__main__':
    app.run(debug=False)

